UPDATE departments
SET department_name = #{request.departmentName},
    updated_at = CURRENT_TIMESTAMP
WHERE department_code = #{request.departmentCode}
    AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

UPDATE departments
SET deleted_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP,
    delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value}
WHERE department_code = #{departmentCode}
AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

UPDATE departments
SET department_name = #{request.departmentName},
    deleted_at = NULL,
    updated_at = CURRENT_TIMESTAMP,
    delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
WHERE department_code = #{request.departmentCode}
AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value}

